package streetfighter;
import nx.updater.*;import javax.swing.*;import java.awt.*;import java.nio.file.*;import java.util.function.BooleanSupplier;
public final class UpdaterScreen {
 private static UpdateService service;
 public static synchronized UpdateService service(){if(service==null)try{Path root=Paths.get(UpdaterScreen.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath();if(!Files.isDirectory(root))root=root.getParent();if(root.getFileName().toString().equals("bin"))root=root.getParent();service=new UpdateService(root);}catch(Exception ex){throw new IllegalStateException(ex);}return service;}
 public static String notice(){try{return service().status;}catch(Exception e){return "NX Updater · configuración no disponible";}}
 public static void show(Component parent,BooleanSupplier canInstall){UpdateService s=service();JDialog d=new JDialog(SwingUtilities.getWindowAncestor(parent),"NX UPDATER",Dialog.ModalityType.MODELESS);d.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);JPanel p=new JPanel(new BorderLayout(12,12));p.setBackground(new Color(29,23,36));p.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));JLabel title=new JLabel("NX UPDATER · NX GAMES / NEXUS Engine");title.setForeground(new Color(235,188,92));p.add(title,BorderLayout.NORTH);JTextArea info=new JTextArea(14,68);info.setEditable(false);info.setLineWrap(true);info.setWrapStyleWord(true);info.setBackground(new Color(39,32,48));info.setForeground(Color.WHITE);p.add(new JScrollPane(info),BorderLayout.CENTER);JPanel lower=new JPanel(new BorderLayout());JProgressBar progress=new JProgressBar(0,1000);progress.setStringPainted(true);lower.add(progress,BorderLayout.NORTH);JPanel buttons=new JPanel(new FlowLayout());
  JButton check=new JButton("COMPROBAR"),update=new JButton("ACTUALIZAR AHORA"),changes=new JButton("VER CAMBIOS"),later=new JButton("MÁS TARDE"),cancel=new JButton("CANCELAR DESCARGA"),restore=new JButton("RESTAURAR ANTERIOR");for(JButton b:new JButton[]{check,update,changes,cancel,restore,later})buttons.add(b);lower.add(buttons,BorderLayout.SOUTH);p.add(lower,BorderLayout.SOUTH);d.setContentPane(p);
  check.addActionListener(e->s.check(true));cancel.addActionListener(e->s.cancel.set(true));later.addActionListener(e->d.dispose());changes.addActionListener(e->{if(s.offer!=null)JOptionPane.showMessageDialog(d,s.offer.manifest.notes,"CAMBIOS",JOptionPane.INFORMATION_MESSAGE);});
  update.addActionListener(e->{if(!canInstall.getAsBoolean()){JOptionPane.showMessageDialog(d,"Termina el combate y desconecta la sala antes de actualizar.");return;}if(s.staged==null){s.download();return;}if(JOptionPane.showConfirmDialog(d,"La descarga está verificada. Cerrar el juego e instalar con respaldo?","NX UPDATER",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{s.launchHelper("install");Window w=SwingUtilities.getWindowAncestor(parent);if(w!=null)w.dispose();System.exit(0);}catch(Exception ex){JOptionPane.showMessageDialog(d,ex.getMessage());}});
  restore.addActionListener(e->{if(!canInstall.getAsBoolean()){JOptionPane.showMessageDialog(d,"Termina la partida y desconecta la sala.");return;}if(JOptionPane.showConfirmDialog(d,"Cerrar el juego y restaurar el respaldo anterior?","NX UPDATER",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{s.launchHelper("restore");System.exit(0);}catch(Exception ex){JOptionPane.showMessageDialog(d,ex.getMessage());}});
  Timer timer=new Timer(150,e->{StringBuilder b=new StringBuilder(s.status).append("\nInstalada: ").append(s.config.installed).append(" · ").append(s.config.platform).append(" · ").append(s.config.channel).append("\nRepositorio: ").append(s.config.repository.isEmpty()?"SIN CONFIGURAR":s.config.repository);b.append("\nDistribución: ").append(s.config.releaseRepository.isEmpty()?"PENDIENTE":s.config.releaseRepository);if(s.offer!=null){b.append("\nDisponible: ").append(s.offer.manifest.version).append("\nDescarga: ").append(s.offer.manifest.totalBytes).append(" bytes\n\n").append(s.offer.manifest.notes).append("\n\nArchivos principales:\n");int n=0;for(UpdateManifest.Entry f:s.offer.manifest.files)if(n++<20)b.append(f.action).append(" ").append(f.path).append('\n');}if(!s.config.configured())b.append("\n\n"+s.config.configurationIssue()+". El juego puede continuar sin Internet.");info.setText(b.toString());progress.setIndeterminate(s.busy&&s.total==0);progress.setValue(s.total==0?0:(int)(s.done*1000/s.total));progress.setString(s.done+" / "+s.total+" bytes · "+s.speed+" B/s · "+(s.total==0?0:s.done*100/s.total)+"%");update.setEnabled(!s.busy&&s.offer!=null);check.setEnabled(!s.busy);});timer.start();d.addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){timer.stop();}});d.pack();d.setLocationRelativeTo(parent);d.setVisible(true);s.check(false);
 }
}
